body:
I thought of that, but the lack of auto typesafety for the `show` string was less than ideal. To show multiple custom errors, it currently does require calling an external function twice — once for validation and another for rendering and the `Field.Validity` component:

```js
import * as React from 'react';
import * as Field from '@base_ui/react/Field';

function validate(value: string) {
  const errors: string[] = [];

  if (value.length < 8) {
    errors.push('Password must be at least 8 characters long.');
  }

  if ((value.match(/[A-Z]/g) ?? []).length < 2) {
    errors.push('Password must contain at least 2 uppercase letters.');
  }

  if ((value.match(/[!@#$%^&*]/g) ?? []).length < 2) {
    errors.push(
      'Password must contain at least 2 unique symbols from the set [!@#$%^&*].',
    );
  }

  return errors;
}

function Password() {
  return (
    <Field.Root
      validateOnChange
      validationDebounceMs={0}
      validate={(value) => {
        const password = value as string;
        const errors = validate(password);
        return errors.length ? 'error' : null;
      }}
    >
      <Field.Control type="password" />
      <Field.Label>Password</Field.Label>
      <Field.Message show="customError" render={<ul />}>
        <Field.Validity>
          {(state) => {
            const password = state.value as string;
            const errors = validate(password);

            if (!errors.length) {
              return null;
            }

            return errors.map((error, index) => <li key={index}>{error}</li>);
          }}
        </Field.Validity>
      </Field.Message>
    </Field.Root>
  );
}
```

